typedef struct {
    int x, y, sum;
} Cell;

int compare_cells(const void *a, const void *b) {
    const Cell *c1 = (const Cell *)a;
    const Cell *c2 = (const Cell *)b;
    if (c1->sum > c2->sum) return -1;
    if (c1->sum < c2->sum) return 1;
    return 0;
}

int main(void) {
    int N, M;
    if (scanf("%d %d", &N, &M) != 2) return 0;

    Cell *cells = (Cell *)malloc((size_t)(2 * M) * sizeof(Cell));
    int count = 0;

    for (int i = 0; i < M; i++) {
        int a, b;
        scanf("%d %d", &a, &b);

        cells[count++] = (Cell){a, b, a + b};
        cells[count++] = (Cell){b, a, a + b};
    }

    qsort(cells, count, sizeof(Cell), compare_cells);

    int *best_f0_by_x = (int *)calloc((size_t)N + 1, sizeof(int));
    int *best_f1_by_y = (int *)calloc((size_t)N + 1, sizeof(int));
    int *answer = (int *)malloc(((size_t)N + 1) * sizeof(int));

    for (int i = 1; i <= N; i++) answer[i] = 1;

    for (int i = 0; i < count; i++) {
        int x = cells[i].x;
        int y = cells[i].y;

        int f0 = 1 + best_f1_by_y[y];
        int f1 = 1 + best_f0_by_x[x];

        if (f0 > best_f0_by_x[x]) best_f0_by_x[x] = f0;
        if (f1 > best_f1_by_y[y]) best_f1_by_y[y] = f1;

        if (1 + f0 > answer[x]) answer[x] = 1 + f0;
    }

    for (int i = 1; i <= N; i++) {
        if (i > 1) putchar(' ');
